import path from 'node:path';
import { Definition } from '@devvit/protos/lib/Types.js';
import { PLUGIN_NAME } from '@devvit/shared-types/HostnameUtil.js';
import { NonNull } from '@devvit/shared-types/NonNull.js';
import { createRequire } from 'module';
const require = createRequire(import.meta.url);
export async function build(builder, actorDir, provides, uses) {
    const compileResponse = await compile(builder, actorDir, provides, uses);
    return await link(builder, compileResponse);
}
async function compile(builder, actorDir, provides, uses) {
    const filename = path.join(path.dirname(require.resolve('@devvit/internal-examples')), actorDir);
    const info = {
        name: filename.split(path.sep).at(-1) ?? '',
        owner: 'snoo',
        version: '0.0.0',
    };
    const request = {
        entry: 'main.ts',
        dependencies: {
            actor: info,
            hostname: `${info.name}.local`,
            provides: provides.map((definition) => ({
                actor: info,
                definition: Definition.toSerializable(definition),
                partitionsBy: [],
            })),
            uses: uses.map((definition) => ({ name: PLUGIN_NAME, typeName: definition.fullName })),
            permissions: [],
        },
        info,
        minify: 'None',
        root: filename,
    };
    const response = await builder.pack.compile(request);
    expect(response.errors).toHaveLength(0);
    expect(response.warnings).toHaveLength(0);
    expect(response.bundles).toHaveLength(1);
    return response;
}
async function link(builder, compileResponse) {
    const linkResponse = await builder.linker.link(compileResponse.bundles[0]);
    expect(linkResponse.errors).toHaveLength(0);
    return NonNull(linkResponse.bundle);
}
